CREATE OR REPLACE VIEW public.v_fato_venda WITH (security_invoker=true) AS
WITH ganho AS (
 SELECT n.id AS negocio_id,n.data_assinatura,n.nome_cliente,n.empreendimento,n.empreendimento_canonico_id,n.pipeline_lead_id,COALESCE(n.vgv_final,n.vgv_estimado,0::numeric) AS valor_negocio,COALESCE(p_prof.user_id,p_auth.user_id) AS corretor_auth_id
 FROM public.negocios n LEFT JOIN public.profiles p_prof ON p_prof.id=n.corretor_id LEFT JOIN public.profiles p_auth ON p_auth.user_id=n.corretor_id
 WHERE n.fase='ganho' AND n.data_assinatura IS NOT NULL AND COALESCE(n.status,'ativo')='ativo'
), participante AS (
 SELECT g.negocio_id,g.corretor_auth_id AS auth_id FROM ganho g WHERE g.corretor_auth_id IS NOT NULL
 UNION SELECT g.negocio_id,pp.corretor_principal_id FROM ganho g JOIN public.pipeline_parcerias pp ON pp.pipeline_lead_id=g.pipeline_lead_id AND pp.status='ativa' WHERE pp.corretor_principal_id IS NOT NULL
 UNION SELECT g.negocio_id,pp.corretor_parceiro_id FROM ganho g JOIN public.pipeline_parcerias pp ON pp.pipeline_lead_id=g.pipeline_lead_id AND pp.status='ativa' WHERE pp.corretor_parceiro_id IS NOT NULL
), rateio AS (SELECT pa.negocio_id,pa.auth_id,count(*) OVER(PARTITION BY pa.negocio_id) AS qtd_participantes FROM participante pa)
SELECT g.negocio_id,g.data_assinatura,date_trunc('month',g.data_assinatura::timestamptz)::date AS mes_ref,g.nome_cliente,g.empreendimento,g.empreendimento_canonico_id,g.pipeline_lead_id,g.valor_negocio,r.auth_id AS corretor_auth_id,pr.nome AS corretor_nome,ce.equipe,ce.gerente_auth_id,COALESCE(ce.corretor_ativo,false) AS corretor_ativo,r.qtd_participantes,r.qtd_participantes>1 AS em_parceria,1::numeric/r.qtd_participantes::numeric AS participacao,round(g.valor_negocio/r.qtd_participantes::numeric,2) AS vgv_rateado,row_number() OVER(PARTITION BY g.negocio_id ORDER BY r.auth_id)=1 AS conta_como_venda
FROM ganho g JOIN rateio r ON r.negocio_id=g.negocio_id LEFT JOIN public.profiles pr ON pr.user_id=r.auth_id LEFT JOIN LATERAL public.fn_equipe_na_data(r.auth_id,g.data_assinatura) ce ON true;
CREATE POLICY vendas_docs_financeiro_privado_leitura ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'vendas-docs' OR name NOT LIKE '%/financeiro/%' OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'diretor'));
CREATE POLICY vendas_docs_financeiro_privado_envio ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'vendas-docs' OR name NOT LIKE '%/financeiro/%' OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'diretor'));
CREATE POLICY vendas_docs_financeiro_preservar ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'vendas-docs' OR NOT EXISTS(SELECT 1 FROM public.negocios_recebimentos r WHERE r.comprovante_path=name) AND NOT EXISTS(SELECT 1 FROM public.financeiro_repasses r WHERE r.comprovante_path=name));